index 0000000000000000000000000000000000000000..78ff49177e3334cb036a374533e659229a9bd685
--- /dev/null
+++ b/Integrations/GeneratedReport/Sources/FieldLogAndroid/SignedChecklistReorder.swift
@@ -0,0 +1,98 @@
+#if FIELDLOG_SIGNED_CHECKLIST
+import FieldLogFeatures
+@_spi(FieldLogChecklistReorder) import FieldLogInstalledGuest
+import FieldLogModels
+import FieldLogStorage
+import Foundation
+@_spi(InstalledApplicationStorage) import MixerCapabilities
+
+final class SignedChecklistReorder: InstalledApplicationStorageServing, @unchecked Sendable {
+    private enum State { case awaitingHydration, hydrated, retired }
+    private let lock = NSLock()
+    private var state = State.awaitingHydration
+    private let repository: WorkspaceRepository
+    private let workspaceID: UUID
+    private let plan: WorkspacePresentation.TaskPlan
+    private let response: KVGetResponse
+
+    private static let namespace = FieldLogSignedTask.checklistReorderNamespace
+    private static let hydration = KVGetArguments(namespace: namespace, key: "current-row")
+    private static let facts = KVGetArguments(namespace: namespace, key: "move-down-facts")
+    private static let action = "checklist.moveDown"
+    private static let node = "toggle"
+    private static let command = KVPutArguments(namespace: namespace, key: "move-down", valueBase64: "AQ==")
+
+    init(repository: WorkspaceRepository, workspaceID: UUID, plan: WorkspacePresentation.TaskPlan, rowNumber: UInt64) {
+        self.repository = repository
+        self.workspaceID = workspaceID
+        self.plan = plan
+        // Eight-byte big-endian row number and one eligibility byte.
+        var bytes = withUnsafeBytes(of: rowNumber.bigEndian) { Data($0) }
+        bytes.append(1)
+        response = .init(found: true, valueBase64: bytes.base64EncodedString())
+    }
+
+    func revoke() { lock.withLock { state = .retired } }
+
+    var continuation: InstalledGuestUICommitFacts {
+        .init(arguments: Self.facts, nodeID: Self.node, actionID: Self.action,
+              commitArguments: Self.command, hydrationArguments: Self.hydration) { [self] event in
+            guard event.isLive, lock.withLock({ state == .hydrated }) else {
+                throw CapabilityFailure.permissionDenied
+            }
+            try await requireCurrentWorkspace()
+            guard event.isLive, lock.withLock({ state == .hydrated }) else {
+                throw CapabilityFailure.permissionDenied
+            }
+            return .init(response: response) { permit in try await self.move(permit) }
+        }
+    }
+
+    func get(_ arguments: KVGetArguments) async throws -> KVGetResponse {
+        guard arguments == Self.hydration, lock.withLock({ state == .awaitingHydration }) else {
+            throw CapabilityFailure.permissionDenied
+        }
+        try await requireCurrentWorkspace()
+        return try lock.withLock {
+            try Task.checkCancellation()
+            guard state == .awaitingHydration else { throw CapabilityFailure.permissionDenied }
+            state = .hydrated
+            return response
+        }
+    }
+
+    func put(_ arguments: KVPutArguments, maximumTotalBytes: Int, maximumEntries: Int) throws -> KVMutationResponse {
+        throw CapabilityFailure.permissionDenied
+    }
+
+    func delete(_ arguments: KVDeleteArguments) throws -> KVMutationResponse {
+        throw CapabilityFailure.permissionDenied
+    }
+
+    private func requireCurrentWorkspace() async throws {
+        try Task.checkCancellation()
+        let snapshot = try await repository.readCommittedSnapshot()
+        guard snapshot.id == workspaceID, snapshot.revision == plan.revision else {
+            throw CapabilityFailure.permissionDenied
+        }
+    }
+
+    private func move(_ permit: InstalledGuestUICommitPermit) async throws -> KVMutationResponse {
+        do {
+            try await repository.transact(expectedRevision: plan.revision) { [self] next in
+                try lock.withLock {
+                    guard state == .hydrated, next.id == workspaceID else {
+                        throw CapabilityFailure.permissionDenied
+                    }
+                    try permit.consume()
+                    try plan.apply(to: &next)
+                    state = .retired
+                }
+            }
+        } catch FieldLogError.staleRevision {
+            throw CapabilityFailure.permissionDenied
+        }
+        return .init(committed: true)
+    }
+}
+#endif
