"""Serve only the two sealed FieldLog F02 releases on an owned loopback port."""
import argparse
import base64
import hashlib
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
from pathlib import Path
from urllib.parse import parse_qs, urlencode, urlsplit
from uuid import UUID

SCOPE = {"organization": "mixer-local", "project": "fieldlog", "app": "fieldlog",
         "environment": "development", "platform": "android"}
TENANT = {key: SCOPE[key] for key in ("organization", "project")}
RELEASE = ("optional.manifest.json", "optional.wasm", "sequence-1.assignment.json")
INSTALLED = ("bridge.json", "identity.json", "port.txt", "roots.json", "storage-grant.json", "storage.json")


def packets(delivery):
    pins = json.loads((delivery / "origin-sha256.json").read_bytes())
    expected = {f"{mode}/{name}" for mode in ("draft", "move") for name in INSTALLED + RELEASE}
    if set(pins) != expected or {p.relative_to(delivery / "origin").as_posix()
                                  for p in (delivery / "origin").glob("*/*")} != expected:
        raise ValueError("Unexpected origin inventory")
    values = {}
    for name in expected:
        path = delivery / "origin" / name
        if path.parent.is_symlink() or path.is_symlink() or not path.is_file() or path.stat().st_size > 131072:
            raise ValueError("Invalid origin input " + name)
        value = path.read_bytes()
        if hashlib.sha256(value).hexdigest() != pins[name]:
            raise ValueError("Unpinned origin input " + name)
        values[name] = value
    offer, artifact = {}, {}
    for mode in ("move", "draft"):
        manifest, wasm, assignment = (values[f"{mode}/{name}"] for name in RELEASE)
        manifest, assignment = json.loads(manifest), json.loads(assignment)
        fields = assignment["assignment"]
        if fields["scope"] != SCOPE or fields["channel"] != "beta" or fields["sequence"] != 1:
            raise ValueError("Origin scope mismatch")
        if manifest["manifest"]["scope"] != SCOPE or manifest["manifest"]["runtime"] != fields["runtime"]:
            raise ValueError("Origin runtime mismatch")
        path = "/v3/artifacts/" + fields["artifact_sha256"]
        offer[fields["runtime"]] = {"signed_assignment": assignment, "artifact_url": path + "?" + urlencode(TENANT)}
        artifact[path] = {"signed_manifest": manifest, "payload": base64.b64encode(wasm).decode("ascii")}
    if len(offer) != 2 or len(artifact) != 2:
        raise ValueError("Expected independently scoped draft and reorder runtimes")
    return offer, artifact


def handler(offers, artifacts, installation):
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            target = urlsplit(self.path)
            parts = parse_qs(target.query, keep_blank_values=True, max_num_fields=10)
            if any(len(values) != 1 for values in parts.values()):
                return self.respond(400)
            query = {key: values[0] for key, values in parts.items()}
            if target.path in artifacts and query == TENANT:
                return self.respond(200, artifacts[target.path])
            if target.path == "/v3/updates":
                runtime = query.pop("runtime", "")
                if query == SCOPE | {"channel": "beta", "installation": installation} and runtime in offers:
                    return self.respond(200, offers[runtime])
                return self.respond(204)
            return self.respond(404)

        def respond(self, status, value=None):
            body = b"" if value is None else json.dumps(value, separators=(",", ":")).encode()
            self.send_response(status)
            self.send_header("Content-Length", str(len(body)))
            if body:
                self.send_header("Content-Type", "application/json")
            self.end_headers()
            if body:
                self.wfile.write(body)

    return Handler


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("delivery", type=Path)
    parser.add_argument("--port", type=int, default=0)
    parser.add_argument("--installation", type=UUID, required=True)
    args = parser.parse_args()
    offers, artifacts = packets(args.delivery)
    with HTTPServer(("127.0.0.1", args.port), handler(offers, artifacts, str(args.installation))) as server:
        print(server.server_port, flush=True)
        server.serve_forever()


if __name__ == "__main__":
    main()

