package dev.mixer.android;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Closed decoder for the ordinary FieldLog signed checklist panel. */
public final class ChecklistFrame {
    public record Decoded(List<String> labels, String action, boolean reorder) {}

    public static Decoded decode(byte[] packet) {
        Map<String, Object> frame = Json.object(Json.parse(packet));
        require("1".equals(Json.uint(frame.get("schemaVersion")))
            && !"0".equals(Json.uint(frame.get("revision"))));
        Map<String, Object> root = node(frame.get("root"), "fieldlog-draft", "vStack");
        require(Json.object(root.get("properties")).isEmpty() && Json.array(root.get("actions")).isEmpty());
        List<Object> children = Json.array(root.get("children"));
        require(children.size() == 3 || children.size() == 4);
        Map<String, Object> button = node(children.get(children.size() - 1), "toggle", "button");
        List<Object> commands = Json.array(button.get("actions"));
        require(Json.array(button.get("children")).isEmpty() && commands.size() == 1);
        Map<String, Object> command = Json.object(commands.get(0));
        Json.keys(command, "id", "event");
        require("activate".equals(Json.string(command.get("event"))));
        String actionID = Json.string(command.get("id"));
        boolean reorder = "checklist.moveDown".equals(actionID);
        require(reorder ? children.size() == 4 : "draft.action".equals(actionID));
        List<String> ids = reorder ? List.of("row", "status", "scope") : List.of("validation", "photo", "follow-up");
        List<String> labels = new ArrayList<>();
        for (int index = 0; index < children.size() - 1; index++) {
            Map<String, Object> text = node(children.get(index), ids.get(index), "text");
            require(Json.array(text.get("children")).isEmpty() && Json.array(text.get("actions")).isEmpty());
            Map<String, Object> properties = Json.object(text.get("properties"));
            Json.keys(properties, "text");
            labels.add(Json.string(properties.get("text")));
        }
        Map<String, Object> properties = Json.object(button.get("properties"));
        Json.keys(properties, "label");
        String action = Json.string(properties.get("label"));
        require(!reorder || "Move down".equals(action));
        return new Decoded(List.copyOf(labels), action, reorder);
    }

    private static Map<String, Object> node(Object value, String id, String kind) {
        Map<String, Object> node = Json.object(value);
        require(id.equals(Json.string(node.get("id"))) && kind.equals(Json.string(node.get("kind"))));
        return node;
    }

    private static void require(boolean condition) {
        if (!condition) throw new IllegalArgumentException("Unsupported FieldLog checklist presentation");
    }

    private ChecklistFrame() {}
}

