import java.nio.file.Path;

public final class JavaBindingReplay {
    public static void main(String[] args) throws Exception {
        byte[] binding = Files.readAllBytes(Path.of(args[0]));
        byte[] roster = Files.readAllBytes(Path.of(args[1]));
        byte[] identity = Files.readAllBytes(Path.of(args[2]));
        ChecklistBuildBinding.verify(binding, identity, roster, Path.of(args[3]));
        System.out.println("ADMITTED exact ELF, VM identity, roster and 50 ms");
        try {
            ChecklistBuildBinding.verify(binding, identity, roster, Path.of(args[4]));
            throw new AssertionError("Wrong linked ELF admitted");
        } catch (IOException refusal) {
            if (!refusal.getMessage().equals("Development checklist build binding refused")) throw refusal;
            System.out.println("REFUSED changed linked ELF");
        }
        roster[0] ^= 1;
        try {
            ChecklistBuildBinding.verify(binding, identity, roster, Path.of(args[3]));
            throw new AssertionError("Wrong linked roster admitted");
        } catch (IOException refusal) {
            if (!refusal.getMessage().equals("Development checklist build binding refused")) throw refusal;
            System.out.println("REFUSED changed linked roster");
        }
    }
}

