package dev.mixer.android;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

public final class JavaFrameReplay {
    public static void main(String[] args) throws Exception {
        boolean move = false;
        boolean draft = false;
        for (String file : args) {
            byte[] bytes = Files.readAllBytes(Path.of(file));
            ChecklistFrame.Decoded frame = ChecklistFrame.decode(bytes);
            move |= frame.reorder();
            draft |= !frame.reorder();
            System.out.println(Path.of(file).getFileName() + " " + frame);
            Map<String, Object> document = Json.object(Json.parse(bytes));
            Map<String, Object> root = Json.object(document.get("root"));
            var children = Json.array(root.get("children"));
            var button = Json.object(children.get(children.size() - 1));
            var action = Json.object(Json.array(button.get("actions")).get(0));
            action.put("id", frame.reorder() ? "draft.action" : "checklist.moveDown");
            try {
                ChecklistFrame.decode(Json.encode(document));
                throw new AssertionError("cross-profile action admitted");
            } catch (IllegalArgumentException expected) {
                System.out.println("REFUSED cross-profile action");
            }
        }
        if (!move || !draft) throw new AssertionError("missing real draft or reorder packet");
    }
}

