package dev.mixer.android;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public final class ChecklistBuildBinding {
    public static void verify(byte[] binding, byte[] identity, byte[] roster, Path nativeLibraries, Path baseApk) throws IOException {
        try {
            Map<String, Object> document = Json.object(Json.parse(identity));
            Map<String, Object> application = Json.object(document.get("application"));
            Map<String, Object> platform = Json.object(document.get("platform"));
            Map<String, Object> policy = Json.object(document.get("capability_execution"));
            String[] pins = new String(binding, StandardCharsets.US_ASCII).split("\n", -1);
            if (pins.length != 7 || !pins[0].equals("fieldlog-f02-build-v2") || !pins[6].isEmpty()
                    || !pins[1].equals(fileDigest(nativeLibraries.resolve("libAppAndroid.so")))
                    || !pins[2].equals(fileDigest(nativeLibraries.resolve("libmixer_public_android_jni.so")))
                    || !pins[3].equals(Json.string(Json.object(document.get("engine")).get("artifact_sha256")))
                    || !pins[4].equals(digest(roster))
                    || !pins[5].equals(dexDigest(baseApk))
                    || !digest(binding).equals(Json.string(Json.object(document.get("build")).get("link_inputs_sha256")))
                    || !"mixer-local".equals(Json.string(application.get("organization")))
                    || !"fieldlog".equals(Json.string(application.get("project")))
                    || !"fieldlog".equals(Json.string(application.get("app")))
                    || !"development".equals(Json.string(application.get("environment")))
                    || !"dev.fieldlog.generatedr90".equals(Json.string(application.get("bundle_id")))
                    || !"android".equals(Json.string(platform.get("os")))
                    || !"arm64".equals(Json.string(platform.get("architecture")))
                    || !"device".equals(Json.string(platform.get("environment")))
                    || !"aarch64-unknown-linux-android28".equals(Json.string(platform.get("target")))
                    || !"50".equals(Json.uint(policy.get("turn_milliseconds")))
                    || !"28".equals(Json.string(platform.get("minimum_os")))) {
                throw new IOException("Development checklist build binding refused");
            }
        } catch (IllegalArgumentException failure) {
            throw new IOException("Malformed checklist build binding", failure);
        }
    }

    private static String dexDigest(Path baseApk) throws IOException {
        try (ZipFile apk = new ZipFile(baseApk.toFile())) {
            ZipEntry dex = null;
            var entries = apk.entries();
            while (entries.hasMoreElements()) {
                ZipEntry entry = entries.nextElement();
                String name = entry.getName();
                if (!name.matches("classes[0-9]*\\.dex")) continue;
                if (dex != null || !name.equals("classes.dex")) {
                    throw new IOException("Unexpected APK DEX inventory");
                }
                dex = entry;
            }
            if (dex == null) throw new IOException("Missing APK DEX");
            try (InputStream stream = apk.getInputStream(dex)) {
                return streamDigest(stream);
            }
        }
    }

    private static String fileDigest(Path file) throws IOException {
        try (InputStream stream = Files.newInputStream(file)) {
            return streamDigest(stream);
        }
    }

    private static String streamDigest(InputStream stream) throws IOException {
        MessageDigest digest = sha256();
        byte[] buffer = new byte[65536];
        long remaining = 64 * 1024 * 1024;
        for (int count; (count = stream.read(buffer)) != -1;) {
            remaining -= count;
            if (remaining < 0) throw new IOException("Checklist build artifact bound");
            digest.update(buffer, 0, count);
        }
        return HexFormat.of().formatHex(digest.digest());
    }

    private static String digest(byte[] bytes) {
        return HexFormat.of().formatHex(sha256().digest(bytes));
    }

    private static MessageDigest sha256() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException impossible) {
            throw new AssertionError(impossible);
        }
    }

    private ChecklistBuildBinding() {}
}

