package dev.fieldlog.generatedr90.androidhost;

import android.graphics.Insets;
import android.view.View;
import android.view.WindowInsets;
import android.widget.FrameLayout;
import java.util.Arrays;

public final class FooterInsetsReplay {
    private static final Insets NONE = new Insets(0, 0, 0, 0);

    public static void main(String[] args) {
        FrameLayout content = new FrameLayout();
        View root = new View();
        View footer = new View();
        FrameLayout.LayoutParams base = new FrameLayout.LayoutParams();
        base.setMargins(2, 3, 4, 5);
        footer.setLayoutParams(base);
        FooterInsets.install(content, footer);
        check(footer.getVisibility() == View.INVISIBLE, "Unsafe pre-dispatch footer");

        WindowInsets gestures = new WindowInsets(new Insets(0, 136, 0, 24),
                NONE, new Insets(20, 0, 35, 63));
        apply(content, footer, gestures, 22, 139, 39, 68);
        int writes = footer.layoutWrites;
        apply(content, footer, gestures, 22, 139, 39, 68);
        check(footer.layoutWrites == writes, "Unchanged insets requested another layout");

        WindowInsets buttons = new WindowInsets(new Insets(0, 84, 0, 104), NONE, NONE);
        apply(content, footer, buttons, 2, 87, 4, 109);
        WindowInsets landscape = new WindowInsets(new Insets(0, 40, 96, 0),
                new Insets(72, 0, 0, 0), new Insets(11, 0, 15, 28));
        apply(content, footer, landscape, 74, 43, 100, 33);
        apply(content, footer, new WindowInsets(NONE, NONE, NONE), 2, 3, 4, 5);
        check(content.layoutWrites == 0 && root.layoutWrites == 0, "Non-footer frame changed");
        System.out.println("PASS deferred visibility, gesture and button navigation, side/cutout, redispatch, and inset removal");
    }

    private static void apply(FrameLayout frame, View footer, WindowInsets value, int... expected) {
        check(frame.dispatchInsets(value) == value, "Insets were consumed");
        check(footer.getVisibility() == View.VISIBLE, "Footer stayed hidden after insets");
        FrameLayout.LayoutParams p = (FrameLayout.LayoutParams) footer.getLayoutParams();
        int[] actual = {p.leftMargin, p.topMargin, p.rightMargin, p.bottomMargin};
        check(Arrays.equals(actual, expected), "Insets produced margins " + Arrays.toString(actual));
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

