        System.out.println("ADMITTED exact APK DEX, ELFs, runtime identity, compiler roster and 50 ms");
        refuses("altered linked ELF", binding, identity, roster, Path.of(args[5]), apk,
                "Development checklist build binding refused");
        refuses("altered DEX", binding, identity, roster, libraries, Path.of(args[6]),
                "Development checklist build binding refused");
        refuses("extra DEX", binding, identity, roster, libraries, Path.of(args[7]),
                "Unexpected APK DEX inventory");
        refuses("missing DEX", binding, identity, roster, libraries, Path.of(args[8]),
                "Missing APK DEX");
        refuses("old installed identity", binding, Files.readAllBytes(Path.of(args[9])), roster, libraries, apk,
                "Development checklist build binding refused");
        roster[0] ^= 1;
        refuses("altered compiler roster", binding, identity, roster, libraries, apk,
                "Development checklist build binding refused");
    }

    private static void refuses(String label, byte[] binding, byte[] identity, byte[] roster,
            Path libraries, Path apk, String reason) throws IOException {
        try {
            ChecklistBuildBinding.verify(binding, identity, roster, libraries, apk);
        } catch (IOException refusal) {
            if (!reason.equals(refusal.getMessage())) throw refusal;
            System.out.println("REFUSED " + label);
            return;
        }
        throw new AssertionError(label + " admitted");
    }
}

