package android.view;


public class View {
    public static final int VISIBLE = 0;
    public static final int INVISIBLE = 4;

    @FunctionalInterface
    public interface OnApplyWindowInsetsListener {
        WindowInsets onApplyWindowInsets(View view, WindowInsets insets);
    }

    private int visibility = VISIBLE;
    private ViewGroup.LayoutParams layout;
    private OnApplyWindowInsetsListener insetsListener;
    public int layoutWrites;

    public void setVisibility(int value) { visibility = value; }
    public int getVisibility() { return visibility; }
    public ViewGroup.LayoutParams getLayoutParams() { return layout; }

    public void setLayoutParams(ViewGroup.LayoutParams value) {
        layout = value;
        layoutWrites++;
    }

    public void setOnApplyWindowInsetsListener(OnApplyWindowInsetsListener value) {
        insetsListener = value;
    }

    public WindowInsets dispatchInsets(WindowInsets insets) {
        return insetsListener.onApplyWindowInsets(this, insets);
    }
}

package android.view;

public class ViewGroup extends View {
    public static class LayoutParams {}
}

package android.view;

import android.graphics.Insets;

public final class WindowInsets {
    public static final class Type {
        public static int systemBars() { return 1; }
        public static int displayCutout() { return 2; }
        public static int systemGestures() { return 4; }
    }

    private final Insets bars, cutout, gestures;

    public WindowInsets(Insets bars, Insets cutout, Insets gestures) {
        this.bars = bars;
        this.cutout = cutout;
        this.gestures = gestures;
    }

    public Insets getInsets(int mask) {
        if (mask != (Type.systemBars() | Type.displayCutout() | Type.systemGestures())) {
            throw new AssertionError("Footer must ask Android for the three relevant inset types");
        }
        return new Insets(Math.max(bars.left, Math.max(cutout.left, gestures.left)),
                Math.max(bars.top, Math.max(cutout.top, gestures.top)),
                Math.max(bars.right, Math.max(cutout.right, gestures.right)),
                Math.max(bars.bottom, Math.max(cutout.bottom, gestures.bottom)));
    }
